 SwingMatch m;bool had,restored;string saved,folder;int errors,releases,lands;float maxEnergy,maxAngle;readonly StringBuilder log=new StringBuilder();void Check(bool ok,string label){log.AppendLine((ok?"PASS ":"FAIL ")+label);if(!ok)errors++;Write();}void Write(){File.WriteAllText(folder+"/progress.txt",log.ToString());}void Error(string s,string stack,LogType type){if(type==LogType.Error||type==LogType.Exception){errors++;log.AppendLine("ERROR "+s);Write();}}
 IEnumerator Start(){folder=SportsEvidencePaths.Folder("SwingEvidence");yield return SportsProbeScene.Ensure<SwingMatch>("TruckGiantSwing");m=FindAnyObjectByType<SwingMatch>();yield return null;had=LWS.TruckSports.SportsPrefs.HasKey(m.PreferenceKey);saved=LWS.TruckSports.SportsPrefs.GetString(m.PreferenceKey);File.WriteAllText(folder+"/preferences-before.json",JsonUtility.ToJson(new Pref{had=had,value=saved}));Application.logMessageReceived+=Error;m.setup.count=8;m.NormalizeSetup();m.AllBots();for(int i=0;i<8;i++)m.setup.players[i].difficulty=(BowlingDifficulty)(i%3);Check(m.StartMatch(),"eight AI turn-based pendulum match starts without devices");Time.timeScale=4;float end=Time.realtimeSinceStartup+900,next=0;SwingPhase before=m.Phase;int lastLocks=0;bool pause=false;while(!m.Finished&&Time.realtimeSinceStartup<end){maxEnergy=Mathf.Max(maxEnergy,m.Energy);maxAngle=Mathf.Max(maxAngle,Mathf.Abs(m.Angle));if(m.Phase==SwingPhase.Flight&&before!=SwingPhase.Flight){releases++;Check(m.ReleaseVelocity.magnitude>2,"actual pendulum release has inherited physical velocity slot="+m.Current+" v="+m.ReleaseVelocity+" angle="+m.Angle+" energy="+m.Energy);if(!pause){pause=true;m.Pause();var p=m.truck.body.position;float age=m.FlightAge;yield return new WaitForSecondsRealtime(.15f);Check(m.Paused&&p==m.truck.body.position&&age==m.FlightAge,"pause preserves free physical flight");m.Resume();Time.timeScale=4;}}if(m.Locks!=lastLocks){lands++;lastLocks=m.Locks;Check(m.LockedScore==SwingRules.Zone(m.LandingPoint,m.LayoutIndex),"first-ground body reference yields correct single zone lock slot="+m.Current+" score="+m.LockedScore+" at="+m.LandingPoint);log.AppendLine("ATTEMPT round="+m.Round+" slot="+m.Current+" totals="+string.Join(",",m.points));}if(Time.realtimeSinceStartup>=next){File.WriteAllText(folder+"/progress.txt",log+"LIVE round="+m.Round+" slot="+m.Current+" phase="+m.Phase+" age="+m.Age+" angle="+m.Angle+" energy="+m.Energy+" points="+string.Join(",",m.points)+" errors="+errors);next=Time.realtimeSinceStartup+2;}before=m.Phase;yield return null;}Check(m.Finished&&m.Winner>=0&&m.Locks>=24,"complete actual eight-AI three-attempt match and genuine tie resolution");Check(maxAngle>30&&maxEnergy>800,"timed physical pumping builds meaningful bounded momentum max angle="+maxAngle+" energy="+maxEnergy);Check(releases>=24&&lands>=24,"every competitor physically releases and lands three attempts");int nonzero=0;for(int i=0;i<8;i++)if(m.points[i]>0)nonzero++;Check(nonzero>=4,"scoring targets are physically reachable by several competitors actual totals="+string.Join(",",m.points));Check(FindObjectsByType<AudioListener>(FindObjectsInactive.Exclude).Length==1,"one audio listener");log.AppendLine("ERRORS="+errors+". Actual PhysX pendulum torque/joints, inherited release and first contact; no human/hardware validation.");File.WriteAllText(folder+"/result.txt",log.ToString());Debug.Log("SWING_PROBE_COMPLETE "+log);Restore();if(!Application.isEditor)Application.Quit(errors==0?0:2);}
